package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.*;
import thaumcraft.content.SimpleContent;
import thaumcraft.thaumaturgy.*;
import thaumcraft.equipment.*;
import thaumcraft.research.*;
import thaumcraft.crystals.*;
import thaumcraft.aura.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class ThaumaturgyProbe {
    public static final BlockPos P=new BlockPos(8,205,8);static int ticks;static ServerPlayer player;static FocalEntity table;static boolean tested,prepared;
    public static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    public static ItemStack item(String id){return new ItemStack(SimpleContent.ITEMS.get(id).get());}
    public static void knowledge(ServerPlayer p){var state=KnowledgeState.EMPTY;for(var e:ResearchCatalog.ENTRIES)state=state.stage(e.key(),e.stages().size()+1);check(KnowledgeStore.write(p,state),"Cannot prepare research");}
    @SubscribeEvent public static void start(ServerStartedEvent e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(mode.isEmpty()||mode.equals("client")||(mode.startsWith("advanced-")||mode.startsWith("plan-")||mode.startsWith("bat-rift-")||mode.startsWith("options-")||mode.startsWith("deep-")||mode.startsWith("golem-")||mode.startsWith("logistics-")))return;var l=e.getServer().overworld();l.setChunkForced(0,0,true);player=new ServerPlayer(e.getServer(),l,new GameProfile(UUID.fromString("04ab25d9-1038-41ef-8de7-fd47e5bfef02"),"ThaumaturgyProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(net.minecraft.network.chat.Component c,boolean overlay){}@Override protected net.minecraft.world.item.ItemCooldowns createItemCooldowns(){return new net.minecraft.world.item.ItemCooldowns();}};player.setPos(8.5,205,8.5);knowledge(player);if(mode.equals("read")){table=(FocalEntity)l.getBlockEntity(P);check(table!=null&&table.working()&&table.remaining()<table.total()&&table.remaining()>0,"Focal job not saved mid-progress");check(table.inventory.getItem(0).getHoverName().getString().equals("Restart focus"),"Focus components lost");}else{l.setBlockAndUpdate(P,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(P,ThaumaturgyContent.TABLE.get().defaultBlockState());table=(FocalEntity)l.getBlockEntity(P);}}
    public static void rules(ServerPlayer p,FocalEntity f){var l=p.level();knowledge(p);p.getAbilities().instabuild=false;p.experienceLevel=30;p.setPos(f.getBlockPos().getX()+.5,f.getBlockPos().getY()+1,f.getBlockPos().getZ()+.5);var program=new FocusProgram("touch",List.of(new FocusProgram.Effect("fire",2,1)));f.draft=program;var focus=item("focus_1");focus.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Restart focus"));f.inventory.setItem(0,focus);
        int levels=p.experienceLevel;check(!f.start(p)&&p.experienceLevel==levels&&!f.working(),"Missing crystals consumed XP");int i=1;for(var c:program.crystals().entrySet())f.inventory.setItem(i++,CrystalContent.essence(c.getKey(),c.getValue()));check(f.start(p)&&p.experienceLevel==levels-program.levels(),"Focal payment failed");check(!f.start(p)&&p.experienceLevel==levels-program.levels(),"Duplicate job debited XP");var menu=new FocalMenu(4,p.getInventory(),f);check(!menu.getSlot(0).mayPickup(p)&&!menu.clickMenuButton(p,3),"In-progress focus can be removed/modified");
        var caster=item("caster_basic");var compiled=item("focus_1");compiled.set(ThaumaturgyContent.PROGRAM.get(),program);p.setItemInHand(InteractionHand.MAIN_HAND,caster);p.setItemInHand(InteractionHand.OFF_HAND,compiled);check(((CasterItem)caster.getItem()).swap(p,caster)&&p.getOffhandItem().isEmpty()&&ItemStack.matches(caster.get(ThaumaturgyContent.FOCUS.get()),compiled),"Physical focus installation lost components");check(((CasterItem)caster.getItem()).swap(p,caster)&&!caster.has(ThaumaturgyContent.FOCUS.get())&&ItemStack.matches(p.getOffhandItem(),compiled),"Focus removal duplicated/lost stack");
        var protection=l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.PROTECTION);var proof=new ItemStack(Items.IRON_CHESTPLATE);var requirement=ResearchCatalog.BY_KEY.get("RUNICSHIELDING").stages().getFirst().items().getFirst();check(!requirement.matches(proof),"Unenchanted runic research accepted");proof.enchant(protection,1);check(requirement.matches(proof),"Protection research requirement unavailable");
        check(item("primal_crusher").getDestroySpeed(Blocks.DIRT.defaultBlockState())>1&&item("primal_crusher").getDestroySpeed(Blocks.STONE.defaultBlockState())>1,"Crusher lost combined mining types");
        var recipe=l.recipeAccess().getRecipes().stream().map(h->h.value()).filter(r->r instanceof thaumcraft.infusion.InfusionRecipe inf&&inf.enchantment().equals("runic")).map(r->(thaumcraft.infusion.InfusionRecipe)r).findFirst().orElseThrow();
        var original=new net.minecraft.world.item.ItemStack(Items.DIAMOND_HELMET);var input=new thaumcraft.infusion.InfusionInput(original,List.of(new net.minecraft.world.item.ItemStack(thaumcraft.crafting.ArcaneContent.SALIS.get()),new net.minecraft.world.item.ItemStack(thaumcraft.content.BasicContent.AMBER.get())));check(recipe.matches(input,l)&&recipe.aspects(input).get("praemunio")==40&&EquipmentContent.runic(recipe.assemble(input))==1,"Runic native recipe failed");
        var armor=EquipmentContent.augment(new ItemStack(Items.DIAMOND_CHESTPLATE));armor.setDamageValue(37);armor.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Runic"));var upgraded=EquipmentContent.augment(armor);check(upgraded.getDamageValue()==37&&upgraded.getHoverName().getString().equals("Runic")&&EquipmentContent.runic(upgraded)==2,"Runic upgrade destroyed components");p.setItemSlot(EquipmentSlot.CHEST,upgraded);p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_ABSORPTION).setBaseValue(4);p.setAbsorptionAmount(4);p.getPersistentData().putFloat("tc_runic_charge",2);var event=new net.minecraftforge.event.entity.living.LivingDamageEvent(p,l.damageSources().magic(),3);net.minecraftforge.event.entity.living.LivingDamageEvent.BUS.post(event);check(event.getAmount()==1&&EquipmentContent.shield(p)==0&&p.getAbsorptionAmount()==4,"Runic absorption wrong: damage="+event.getAmount()+", shield="+EquipmentContent.shield(p)+", absorption="+p.getAbsorptionAmount());p.setItemSlot(EquipmentSlot.HEAD,item("goggles"));check(Math.abs(EquipmentContent.visCost(p,100)-95)<.01,"Goggle discount wrong");p.setItemInHand(InteractionHand.OFF_HAND,item("ring_cloud"));p.setOnGround(false);check(CloudJump.jump(p)&&!CloudJump.jump(p),"Cloud jump allows repeated flight");p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);
        var mob=new net.minecraft.world.entity.monster.zombie.Zombie(l);mob.setPos(p.getX()+2,p.getY(),p.getZ());mob.setNoAi(true);l.addFreshEntity(mob);SpellEngine.apply(p,program,new EntityHitResult(mob));check(mob.getHealth()<mob.getMaxHealth()&&mob.isOnFire(),"Spell fire effect failed");mob.discard();Thaumcraft.LOGGER.info("THAUMATURGY_RULES_OK: atomic focal costs, locked job, physical focus conservation, preserved runic armor, actual absorption, discount, bounded cloud jump and spell damage");}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(mode.isEmpty()||mode.equals("client")||(mode.startsWith("advanced-")||mode.startsWith("plan-")||mode.startsWith("bat-rift-")||mode.startsWith("options-")||mode.startsWith("deep-")||mode.startsWith("golem-")||mode.startsWith("logistics-"))||tested||++ticks<40)return;if(mode.equals("read")){if(table.working())return;check(table.inventory.getItem(0).has(ThaumaturgyContent.PROGRAM.get()),"Resumed focus not completed");tested=true;Thaumcraft.LOGGER.info("THAUMATURGY_RESTART_OK: persisted focal job completed exactly once with named focus");e.server().halt(false);return;}if(!prepared){rules(player,table);prepared=true;return;}if(table.remaining()==table.total())return;tested=true;Thaumcraft.LOGGER.info("THAUMATURGY_WRITE_OK: saved pending focus with paid XP and crystals");e.server().halt(false);}
}
